import dlt
from pyspark.sql.functions import current_timestamp, col

@dlt.table(
    name="bronze_orders",
    comment="Raw orders ingested from cloud storage via Auto Loader",
    table_properties={"quality": "bronze", "pipelines.reset.allowed": "true"}
)
@dlt.expect("has_order_id", "order_id IS NOT NULL")
def bronze_orders():
    return (
        spark.readStream.format("cloudFiles")
            .option("cloudFiles.format", "json")
            .option("cloudFiles.schemaLocation", "/Volumes/main/sales/_schemas/orders")
            .option("cloudFiles.inferColumnTypes", "true")
            .load("/Volumes/main/sales/landing/orders/")
            .withColumn("_ingested_at", current_timestamp())
    )

import dlt
from pyspark.sql.functions import col, to_date

@dlt.table(
    name="silver_orders",
    comment="Cleansed and conformed orders",
    table_properties={"quality": "silver"}
)
@dlt.expect_all_or_drop({
    "valid_order_id": "order_id IS NOT NULL",
    "valid_customer": "customer_id IS NOT NULL",
    "positive_amount": "amount > 0"
})
@dlt.expect_or_fail("valid_currency", "currency IN ('USD','EUR','GBP')")
def silver_orders():
    return (
        dlt.read_stream("bronze_orders")
            .select(
                col("order_id"),
                col("customer_id"),
                col("amount").cast("double"),
                col("currency"),
                to_date(col("order_ts")).alias("order_date")
            )
    )

import dlt
from pyspark.sql.functions import sum as _sum, count

@dlt.table(
    name="gold_daily_revenue",
    comment="Daily revenue and order counts by currency",
    table_properties={"quality": "gold"}
)
def gold_daily_revenue():
    return (
        dlt.read("silver_orders")
            .groupBy("order_date", "currency")
            .agg(
                _sum("amount").alias("total_revenue"),
                count("order_id").alias("order_count")
            )
    )
